                "id": "mn56-upali-conversion",
                "label": "Discourse to Upali (MN 56 Upali Sutta)",
                "description": "Details the conversion of the prominent Jain disciple Upali after a debate on whether bodily or mental action is most blameworthy. The Buddha demonstrates the primacy of volition (cetana) and graciously advises Upali to maintain charitable support for his former teachers."
