                "label": "Shorter Malunkyaputta (MN 63 Culamalunkya Sutta)",
                "description": "Addresses an ascetic who threatens to leave unless metaphysical questions regarding the eternity of the world and soul are resolved. The Buddha responds with the famous poisoned arrow parable, insisting on direct therapy for suffering over speculative philosophy."
