                "id": "mn62-maha-rahulovada",
                "label": "Greater Advice to Rahula (MN 62 Maharahulovada Sutta)",
                "description": "Provides comprehensive meditation instructions on the four primary elements, space, loving-kindness, and the sixteen steps of anapanasati. Developing mind like earth, water, fire, and wind ensures that impressions cannot shake equanimity."
